create or replace function public.twitter_claim_analytics_items(p_worker_id text,p_limit integer)returns table(item_id uuid,attempt_id uuid,organization_id uuid,job_id uuid,resource_type public.twitter_analytics_resource_type,resource_id uuid,profile_id uuid,connection_id uuid,zernio_post_id text,amount_micros bigint)language plpgsql security definer set search_path=public as $$
begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;return query
with ranked as(select i.id,row_number()over(partition by i.profile_id order by i.created_at,i.id)rn from public.twitter_analytics_items i where i.status='reserved'and not exists(select 1 from public.twitter_analytics_items a where a.profile_id=i.profile_id and a.status='processing')),
candidates as(select i.id from public.twitter_analytics_items i join ranked r on r.id=i.id and r.rn=1 order by i.created_at,i.id for update of i skip locked limit least(greatest(p_limit,1),50)),
updated as(update public.twitter_analytics_items i set status='processing',claimed_at=timezone('utc',now()),claimed_by=p_worker_id,attempt_count=attempt_count+1 from candidates c where i.id=c.id returning i.*),
attempts(attempt_id_value,attempt_item_id)as(insert into public.twitter_analytics_attempts(organization_id,item_id,attempt_number,worker_id,idempotency_key)select u.organization_id,u.id,u.attempt_count,p_worker_id,'analytics-attempt:'||u.id||':'||u.attempt_count from updated u returning public.twitter_analytics_attempts.id,public.twitter_analytics_attempts.item_id)
update public.twitter_analytics_jobs j set status='processing',started_at=coalesce(j.started_at,timezone('utc',now()))from updated u where j.id=u.job_id returning u.id,(select attempts.attempt_id_value from attempts where attempts.attempt_item_id=u.id),u.organization_id,u.job_id,u.resource_type,case when u.resource_type='post'then u.publication_item_id else u.profile_id end,u.profile_id,u.connection_id,u.zernio_post_id,u.amount_micros;end$$;
revoke all on function public.twitter_claim_analytics_items(text,integer)from public,anon,authenticated;grant execute on function public.twitter_claim_analytics_items(text,integer)to service_role;
